INSERT INTO `truyen` (`TID`, `NDID`, `TenTruyen`, `MoTa`, `AnhBia`, `TacGia`, `LuotThich`, `DaDuyet`, `LyDoTuChoi`, `TrangThai`, `GioiHan18Tuoi`) VALUES
(1, 1, 'Ushiro No Seki No Gyaru Ni Sukarete Shimatta', 'Mặc dù chả nói chuyện hay tiếp xúc gì đâu nhưng cô ấy lại thích tôi? Có lẽ là bịp chăng?', 'ushiro-no-seki-no-gyaru-ni-sukarete-shimatta_1701219020_074125_26112025_107.jpg', NULL, 0, 1, NULL, 1, 0),
(2, 1, 'Kunon The Sorcerer Can See', NULL, 'kunon-the-sorcerer-can-see_1763653848_074422_26112025_923.jpg', 'Minamino Umikaze, Pandora', 0, 1, NULL, 1, 0),
(3, 1, 'Tsuki Ga Michibiku Isekai Douchuu', 'Học sinh trung học Misumi Makoto bị gọi vào thế giới khác bởi vị thần Tsukuyomi để làm anh hùng. Tuy nhiên xấu trai cũng là một cái tội, vị thần ngứa mắt nên đá chàng trai xuống nhân gian với một chút sức mạnh được ban cho. Giờ đây, Makoto đang tự quyết định vận mệnh của mình...', 'tsuki-ga-michibiku-isekai-douchuu_1443437362_074535_26112025_067.jpg', NULL, 0, 1, NULL, 1, 0),
(4, 1, 'Onepunch Man', 'Onepunch-Man là một Manga thể loại siêu anh hùng với đặc trưng phồng tôm đấm phát chết luôn… Lol!!! Nhân vật chính trong Onepunch-man là Saitama, một con người mà nhìn đâu cũng thấy “tầm thường”, từ khuôn mặt vô hồn, cái đầu trọc lóc, cho tới thể hình long tong. Tuy nhiên, con người nhìn thì tầm thường này lại chuyên giải quyết những vấn đề hết sức bất thường. Anh thực chất chính là một siêu anh hùng luôn tìm kiếm cho mình một đối thủ mạnh. Vấn đề là, cứ mỗi lần bắt gặp một đối thủ tiềm năng, thì đối thủ nào cũng như đối thủ nào, chỉ ăn một đấm của anh là… chết luôn. Liệu rằng Onepunch-Man Saitaman có thể tìm được cho mình một kẻ ác dữ dằn đủ sức đấu với anh? Hãy theo bước Saitama trên con đường một đấm tìm đối cực kỳ hài hước của anh!!', 'onepunch-man_1552232163_074826_26112025_337.jpg', 'Murata Yuusuke, One', 0, 1, NULL, 1, 0),
(5, 1, 'Anh Hùng Nơi Tận Cùng Phương Bắc.', NULL, 'anh-hung-noi-tan-cung-phuong-bac_1754626064981_075055_26112025_245.jpg', NULL, 0, 1, NULL, 1, 1),
(6, 1, 'Tử Thần Quân Vương Trở Về', NULL, 'tu-than-quan-vuong-tro-ve_1756895029252_075516_26112025_948.jpg', NULL, 0, 1, NULL, 1, 0),
(7, 1, 'Blue Lock', 'Yoichi Isagi đã bỏ lỡ cơ hội tham dự giải Cao Trung toàn quốc do đã chuyền cho đồng đội thay vì tự thân mình dứt điểm. Cậu là một trong 300 chân sút U-18 được tuyển chọn bởi Jinpachi Ego, người đàn ông được Hiệp Hội Bóng Đá Nhật Bản thuê sau hồi FIFA World Cup năm 2018, nhằm dẫn dắt Nhật Bản vô địch World Cup bằng cách tiêu diệt nền bóng đá Nhật Bản. Kế hoạch của Ego gồm việc cô lập 300 tay sút trong một nhà ngục - dưới một tổ chức với tên gọi là \"Blue Lock\", với mục tiêu là tạo ra chân sút \"tự phụ\" nhất thế giới, điều mà nền bóng đá Nhật Bản còn thiếu.', 'blue-lock_1557191040_075644_26112025_751.jpg', 'Kaneshiro Muneyuki, Nomura Yuusuke', 0, 1, NULL, 1, 0),
(8, 1, 'One Piece', 'One Piece là câu truyện kể về Luffy và các thuyền viên của mình. Khi còn nhỏ, Luffy ước mơ trở thành Vua Hải Tặc. Cuộc sống của cậu bé thay đổi khi cậu vô tình có được sức mạnh có thể co dãn như cao su, nhưng đổi lại, cậu không bao giờ có thể bơi được nữa. Giờ đây, Luffy cùng những người bạn hải tặc của mình ra khơi tìm kiếm kho báu One Piece, kho báu vĩ đại nhất trên thế giới. Trong One Piece, mỗi nhân vật trong đều mang một nét cá tính đặc sắc kết hợp cùng các tình huống kịch tính, lối dẫn truyện hấp dẫn chứa đầy các bước ngoặt bất ngờ và cũng vô cùng hài hước đã biến One Piece trở thành một trong những bộ truyện nổi tiếng nhất không thể bỏ qua. Hãy đọc One Piece để hòa mình vào một thế giới của những hải tặc rộng lớn, đầy màu sắc, sống động và thú vị, cùng đắm chìm với những nhân vật yêu tự do, trên hành trình đi tìm ước mơ của mình.', 'dao-hai-tac_1552224567_080344_26112025_504.jpg', 'Eiichiro Oda', 0, 1, NULL, 1, 0),
(9, 1, 'Abu Normal', 'Bình thường là gì? Bất thường là gì? Như thế nào mới là bình thường và như thế nào mới là bất thường? Đây là câu chuyện về Abu Eiko, 29 tuổi còn độc thân. Một người không có mong muốn gì hơn ngoài được trở thành một người bình thường.', 'abu-normal_1720233584_080935_26112025_378.jpg', 'Kawakami Yamato', 0, 1, NULL, 1, 0),
(10, 1, 'Saneka No Yomeiri', NULL, 'saneka-no-yomeiri_1753289742705_081037_26112025_857.jpg', NULL, 0, 1, NULL, 1, 0);
